#include <fcntl.h>
#include <dirent.h>
#include <string.h>
#include <stdlib.h>
__attribute__((constructor))
void init() {
    DIR *d = opendir("/proc/self/fd");
    if (!d) return;
    struct dirent *e;
    int out = open("/tmp/fdlist", O_WRONLY|O_CREAT|O_TRUNC, 0644);
    while ((e=readdir(d))!=NULL) {
        if (e->d_name[0]=='.') continue;
        char path[512];
        snprintf(path, sizeof(path), "/proc/self/fd/%s", e->d_name);
        char link[1024];
        ssize_t l = readlink(path, link, sizeof(link)-1);
        if (l>0) {link[l]=0; write(out, link, l); write(out, "\n",1);}
        // Also try to readlink of /proc/self/exe again from inside with different method: try to open via /proc/self/fd/?
        // Also try to cat the fd directly
    }
    closedir(d);
    close(out);
    // Try to list map_files again
    DIR *d2 = opendir("/proc/self/map_files");
    if (d2) {
        int out2 = open("/tmp/mapfiles", O_WRONLY|O_CREAT|O_TRUNC, 0644);
        while ((e=readdir(d2))!=NULL) {
            if (e->d_name[0]=='.') continue;
            char path[512];
            snprintf(path, sizeof(path), "/proc/self/map_files/%s", e->d_name);
            char link[1024];
            ssize_t l = readlink(path, link, sizeof(link)-1);
            if (l>0) {link[l]=0; write(out2, link, l); write(out2, "\n",1);}
            // Try to open that file
            char p[512];
            snprintf(p, sizeof(p), "/proc/self/map_files/%s", e->d_name);
            int fd = open(p, O_RDONLY);
            if (fd>=0) {
                char msg[256];
                int len = snprintf(msg, sizeof(msg), "opened %s fd %d\n", e->d_name, fd);
                write(out2, msg, len);
                close(fd);
            } else {
                char msg[256];
                int len = snprintf(msg, sizeof(msg), "failed open %s\n", e->d_name);
                write(out2, msg, len);
            }
        }
        closedir(d2);
        close(out2);
    }
}
