                elif arg.startswith("-bso") and len(arg)==4:
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nToo short switch:\n{arg}\n")
                    sys.exit(7)
                elif arg.startswith("-bso") and len(arg)==5 and arg[4] not in "012":
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nIncorrect switch postfix:\n{arg}\n")
                    sys.exit(7)
            continue
        else:
            files.append(arg)
