    warnings = []
    for f in files:
        if f.startswith("@"):
            try:
                with open(f[1:],"r") as fh:
                    for line in fh:
                        line=line.strip()
                        if line:
                            expanded.append(line)
            except:
                warnings.append(f)
        else:
            expanded.append(f)
    if not expanded:
        expanded = ["."]
    hash_files = []
    for path in expanded:
        if not os.path.exists(path):
            warnings.append(path)
            continue
        if os.path.isdir(path):
            for root, dirs, files_in in os.walk(path):
                for fn in files_in:
                    hash_files.append(os.path.join(root, fn))
        else:
            if "*" in path or "?" in path:
                matched = glob.glob(path, recursive=False)
                if not matched:
                    warnings.append(path)
                for g in matched:
                    if os.path.isdir(g):
                        for root, dirs, files_in in os.walk(g):
                            for fn in files_in:
