        else:
            table_stream.write(f"{hashes['CRC32']:8} {hashes['CRC64']:16} {hashes['SHA256']:64} {hashes['SHA1']:40} {hashes['XXH64']:16} {len(data):13}  {name}\n")
    if len(hash_names) == 1:
        h = hash_names[0]
        if h == "CRC32":
            table_stream.write("-------- -------------  ------------\n")
