    else:
        table_stream.write("-------- ---------------- ---------------------------------------------------------------- ---------------------------------------- ---------------- -------------  ------------\n")
    if hash_files:
        if len(hash_names) == 1:
            h = hash_names[0]
            if h == "CRC32":
                ch = f"{binascii.crc32(combined) & 0xffffffff:08X}"
                table_stream.write(f"{ch} {len(combined):13}  \n")
            elif h == "CRC64":
                ch = f"{crc64_ecma(combined):016X}"
                table_stream.write(f"{ch} {len(combined):13}  \n")
            elif h == "SHA256":
                ch = hashlib.sha256(combined).hexdigest()
                table_stream.write(f"{ch} {len(combined):13}  \n")
            elif h == "SHA1":
                ch = hashlib.sha1(combined).hexdigest()
                table_stream.write(f"{ch} {len(combined):13}  \n")
            elif h == "XXH64":
                ch = f"{xxh64(combined):016X}"
                table_stream.write(f"{ch} {len(combined):13}  \n")
        else:
            chs = {}
            for hn in hash_names:
                if hn == "CRC32":
                    chs[hn] = f"{binascii.crc32(combined) & 0xffffffff:08X}"
                elif hn == "CRC64":
                    chs[hn] = f"{crc64_ecma(combined):016X}"
                elif hn == "SHA256":
                    chs[hn] = hashlib.sha256(combined).hexdigest()
                elif hn == "SHA1":
