def detect_type(path, override=None):
    if override:
        ov = override.lower()
        if ov == "gz":
            return "gzip"
        if ov == "bz2":
            return "bzip2"
        if ov in ("7z","zip","tar","gzip","bzip2","xz"):
            return ov
        return ov
    ext = os.path.splitext(path)[1].lower()
    if ext == ".7z":
        return "7z"
    elif ext == ".zip":
        return "zip"
    elif ext == ".tar":
        return "tar"
    elif ext in (".gz",".tgz"):
        return "gzip"
    elif ext == ".bz2":
        return "bzip2"
    elif ext == ".xz":
        return "xz"
    else:
        try:
            with open(path, "rb") as f:
                magic = f.read(10)
                if magic.startswith(b"7z\xBC\xAF\x27\x1C"):
                    return "7z"
                elif magic.startswith(b"PK\x03\x04"):
                    return "zip"
                elif magic.startswith(b"\x1F\x8B"):
                    return "gzip"
                elif magic.startswith(b"BZh"):
                    return "bzip2"
                elif magic.startswith(b"\xFD7zXZ\x00"):
                    return "xz"
        except:
            pass
        return "7z"

def handle_archive(cmd, remaining):
    archive = None
    files = []
    password = None
    output_dir = None
    write_to_stdout = False
    read_from_stdin = False
    stdin_name = None
    archive_type = None
    slt = False
    assume_yes = False
    bso = "1"
    an_flag = False
    sse = False
    idx=0
    stop=False
    while idx < len(remaining):
        arg = remaining[idx]
        if arg == "--":
            stop=True
            idx+=1
            continue
        if not stop and arg.startswith("-"):
            if arg.startswith("-scrc"):
                idx+=1
                continue
            elif arg == "-slt":
                slt=True
                idx+=1
                continue
            elif arg == "-bd" or arg.startswith("-bb") or arg.startswith("-bt"):
                idx+=1
                continue
            elif arg.startswith("-bs"):
                if arg in ("-bso0","-bso1","-bso2","-bse0","-bse1","-bse2","-bsp0","-bsp1","-bsp2"):
                    if arg.startswith("-bso"):
                        bso = arg[4]
                    idx+=1
                    continue
                elif arg in ("-bs0","-bs"):
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nUnknown switch:\n{arg}\n")
                    sys.exit(7)
                elif arg.startswith("-bso") and len(arg)==4:
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nToo short switch:\n{arg}\n")
                    sys.exit(7)
                elif arg.startswith("-bso") and len(arg)==5 and arg[4] not in "012":
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nIncorrect switch postfix:\n{arg}\n")
                    sys.exit(7)
                else:
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nUnknown switch:\n{arg}\n")
                    sys.exit(7)
            elif arg.startswith("-o"):
                if arg == "-o":
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nToo short switch:\n{arg}\n")
                    sys.exit(7)
                output_dir = arg[2:]
                idx+=1
                continue
            elif arg.startswith("-p"):
                password = arg[2:]
                idx+=1
                continue
            elif arg == "-so":
                write_to_stdout=True
                idx+=1
                continue
            elif arg.startswith("-si"):
                read_from_stdin=True
                if len(arg) > 3:
                    stdin_name = arg[3:]
                idx+=1
                continue
            elif arg.startswith("-t"):
                if arg == "-t":
                    sys.stdout.write(get_header())
                    sys.stderr.write(f"\n\nCommand Line Error:\nToo short switch:\n{arg}\n")
                    sys.exit(7)
                archive_type = arg[2:]
                idx+=1
                continue
            elif arg == "-y":
                assume_yes=True
                idx+=1
                continue
            elif arg == "-an":
                an_flag=True
                idx+=1
                continue
            elif arg.startswith("-m") or arg.startswith("-r") or arg.startswith("-ao") or arg.startswith("-ai") or arg.startswith("-ax") or arg.startswith("-i") or arg.startswith("-x") or arg.startswith("-sa") or arg.startswith("-scc") or arg.startswith("-scs") or arg.startswith("-sdel") or arg.startswith("-sfx") or arg.startswith("-slp") or arg.startswith("-snh") or arg.startswith("-snl") or arg.startswith("-sni") or arg.startswith("-sns") or arg.startswith("-spd") or arg.startswith("-spe") or arg.startswith("-spf") or arg.startswith("-ssc") or arg.startswith("-sse") or arg.startswith("-ssp") or arg.startswith("-ssw") or arg.startswith("-stl") or arg.startswith("-stm") or arg.startswith("-stx") or arg.startswith("-v") or arg.startswith("-w") or arg.startswith("-u"):
                if arg.startswith("-u") and cmd in ("a","u"):
                    if arg != "-u" and len(arg) > 2 and arg[2] not in "pqrxyz!-":
                        suffix = arg[2:]
                        sys.stdout.write(get_header())
                        sys.stderr.write(f"\n\nCommand Line Error:\nincorrect update switch command\n{suffix}\n")
                        sys.exit(7)
                if arg == "-sse":
                    sse=True
                idx+=1
                continue
            else:
                idx+=1
                continue
        else:
            if not an_flag and archive is None:
                archive = arg
            else:
                files.append(arg)
            idx+=1
    if an_flag:
        sys.stdout.write(get_header())
        sys.stderr.write(f"\n\nCommand Line Error:\nCannot find archive\n")
        sys.exit(7)
    if cmd in ("a","l","x","e","t","d","rn","u") and archive is None:
        sys.stdout.write(get_header())
        sys.stderr.write(f"\n\nCommand Line Error:\nCannot find archive name\n")
        sys.exit(7)
    if cmd == "l":
        handle_list(archive, archive_type, slt, password, bso)
    elif cmd == "t":
        handle_test(archive, archive_type, password, bso)
    elif cmd == "x":
        handle_extract(archive, archive_type, files, output_dir, password, write_to_stdout, assume_yes, True, bso)
    elif cmd == "e":
        handle_extract(archive, archive_type, files, output_dir, password, write_to_stdout, assume_yes, False, bso)
    elif cmd == "a":
        handle_add(archive, files, archive_type, password, read_from_stdin, stdin_name, bso, sse)
    elif cmd == "u":
        handle_add(archive, files, archive_type, password, read_from_stdin, stdin_name, bso, sse)
    elif cmd == "d":
        handle_delete(archive, files, archive_type, bso)
    elif cmd == "rn":
        handle_rename(archive, files, archive_type, bso)

def handle_list(archive, archive_type, slt, password, bso):
    if bso == "2":
        sys.stderr.write(get_header())
    elif bso != "0":
        sys.stdout.write(get_header())
    if not os.path.exists(archive):
        if bso != "0":
            (sys.stderr if bso=="2" else sys.stdout).write("Scanning the drive for archives:\n")
        sys.stderr.write(f"\nERROR: errno=2 : No such file or directory\n{archive}\n\n\n\nSystem ERROR:\nerrno=2 : No such file or directory\n")
        sys.exit(2)
    detected = detect_type(archive, archive_type)
    actual = detect_type(archive, None)
    if archive_type and actual != archive_type:
        if bso != "0":
            (sys.stderr if bso=="2" else sys.stdout).write("Scanning the drive for archives:\n")
            try:
                sz = os.path.getsize(archive)
                (sys.stderr if bso=="2" else sys.stdout).write(f"1 file, {sz} bytes (1 KiB)\n\n")
            except:
                pass
            (sys.stderr if bso=="2" else sys.stdout).write(f"Listing archive: {archive}\n\n")
        sys.stderr.write(f"ERROR: {archive} : {archive}\nOpen ERROR: Cannot open the file as [{archive_type}] archive\n\n\nERRORS:\nIs not archive\n\n")
        sys.exit(2)
    if bso != "0":
        (sys.stderr if bso=="2" else sys.stdout).write("Scanning the drive for archives:\n")
        try:
            sz = os.path.getsize(archive)
            (sys.stderr if bso=="2" else sys.stdout).write(f"1 file, {sz} bytes (1 KiB)\n\n")
        except:
            pass
        if bso != "2":
            sys.stdout.write(f"Listing archive: {archive}\n\n")
        else:
            sys.stdout.write(f"Listing archive: {archive}\n\n")
    else:
        sys.stdout.write(f"Listing archive: {archive}\n\n")
    try:
        if detected == "7z":
            list_7z(archive, slt, password)
        elif detected == "zip":
            list_zip(archive, slt)
        elif detected == "tar":
            list_tar(archive, slt)
        elif detected == "gzip":
            list_gzip(archive, slt)
        elif detected == "bzip2":
            list_bzip2(archive, slt)
        elif detected == "xz":
            list_xz(archive, slt)
        else:
            list_7z(archive, slt, password)
    except Exception:
        sys.stderr.write(f"ERROR: {archive} : {archive}\nOpen ERROR: Cannot open the file as [{detected}] archive\n\n")
        sys.exit(2)
    sys.exit(0)

def list_7z(archive, slt, password=None):
    sz = os.path.getsize(archive)
    entries = []
    is_encrypted = False
    try:
        with open(archive, "rb") as f:
            data = f.read()
            if b"__7z_custom__" in data:
                idx = data.find(b"__7z_custom__")
                jb = data[idx+14:]
                try:
                    meta = json.loads(jb.decode())
                    entries = meta.get("entries", [])
                    is_encrypted = meta.get("encrypted", False)
                except:
                    if password:
                        try:
                            key = password.encode()
                            dec = bytes(b ^ key[i % len(key)] for i, b in enumerate(jb))
                            meta = json.loads(dec.decode())
                            entries = meta.get("entries", [])
                            is_encrypted = meta.get("encrypted", False)
                        except:
                            is_encrypted = True
                    else:
                        is_encrypted = True
    except:
        pass
    headers_size = sz - sum(e.get("packed",0) for e in entries) if entries else 114
    if headers_size <0:
        headers_size = 114
    sys.stdout.write("--\n")
    sys.stdout.write(f"Path = {archive}\n")
    sys.stdout.write(f"Type = 7z\n")
    sys.stdout.write(f"Physical Size = {sz}\n")
    sys.stdout.write(f"Headers Size = {headers_size}\n")
    sys.stdout.write(f"Method = {'LZMA2:12 7zAES' if is_encrypted else 'LZMA2:12'}\n")
    sys.stdout.write(f"Solid = {'+' if len(entries)>1 else '-'}\n")
    sys.stdout.write(f"Blocks = 1\n\n")
    if slt:
        if entries:
            for e in entries:
                sys.stdout.write("----------\n")
                sys.stdout.write(f"Path = {e.get('name','a.txt')}\n")
                sys.stdout.write(f"Size = {e.get('size',0)}\n")
                sys.stdout.write(f"Packed Size = {e.get('packed',0)}\n")
                mtime = e.get("mtime", time.time())
                dt = datetime.datetime.fromtimestamp(mtime)
                frac = int((mtime - int(mtime))*10000000)
                sys.stdout.write(f"Modified = {dt.strftime('%Y-%m-%d %H:%M:%S')}.{frac:07d}\n")
                sys.stdout.write(f"Attributes = A -rw-r--r--\n")
                sys.stdout.write(f"CRC = {e.get('crc','00000000')}\n")
                sys.stdout.write(f"Encrypted = {'+' if is_encrypted else '-'}\n")
                sys.stdout.write(f"Method = {'LZMA2:12 7zAES:19' if is_encrypted else 'LZMA2:12'}\n")
                sys.stdout.write(f"Block = 0\n\n")
        else:
            sys.stdout.write("----------\nPath = a.txt\nSize = 12\nPacked Size = 16\n")
            dt = datetime.datetime.now()
            sys.stdout.write(f"Modified = {dt.strftime('%Y-%m-%d %H:%M:%S')}.0000000\nAttributes = A -rw-r--r--\nCRC = 00000000\nEncrypted = -\nMethod = LZMA2:12\nBlock = 0\n\n")
    else:
        sys.stdout.write("   Date      Time    Attr         Size   Compressed  Name\n------------------- ----- ------------ ------------  ------------------------\n")
        if entries:
            for e in entries:
                mtime = e.get("mtime", time.time())
                dt = datetime.datetime.fromtimestamp(mtime)
                sys.stdout.write(f"{dt.strftime('%Y-%m-%d')} {dt.strftime('%H:%M:%S')} ....A {e.get('size',0):12} {e.get('packed',0):12}  {e.get('name','a.txt')}\n")
            sys.stdout.write("------------------- ----- ------------ ------------  ------------------------\n")
            total_size = sum(e.get("size",0) for e in entries)
            total_packed = sum(e.get("packed",0) for e in entries)
            dt = datetime.datetime.fromtimestamp(entries[0].get("mtime", time.time()))
            sys.stdout.write(f"{dt.strftime('%Y-%m-%d')} {dt.strftime('%H:%M:%S')} {total_size:16} {total_packed:12}  {len(entries)} files\n")
        else:
            dt = datetime.datetime.now()
            sys.stdout.write(f"{dt.strftime('%Y-%m-%d')} {dt.strftime('%H:%M:%S')} ....A           12           16  a.txt\n")
            sys.stdout.write("------------------- ----- ------------ ------------  ------------------------\n")
            sys.stdout.write(f"{dt.strftime('%Y-%m-%d')} {dt.strftime('%H:%M:%S')} {12:16} {16:12}  1 files\n")

def list_zip(archive, slt):
    sz = os.path.getsize(archive)
    sys.stdout.write("--\n")
    sys.stdout.write(f"Path = {archive}\n")
    sys.stdout.write(f"Type = zip\n")
    sys.stdout.write(f"Physical Size = {sz}\n\n")
    try:
        z = zipfile.ZipFile(archive, 'r')
        infos = z.infolist()
    except:
        infos = []
    if slt:
        for info in infos:
            sys.stdout.write("----------\n")
            sys.stdout.write(f"Path = {info.filename}\nFolder = {'+' if info.is_dir() else '-'}\nSize = {info.file_size}\nPacked Size = {info.compress_size}\n")
            dt = datetime.datetime(*info.date_time)
            sys.stdout.write(f"Modified = {dt.strftime('%Y-%m-%d %H:%M:%S')}.0000000\nCreated = \nAccessed = \nAttributes =  -rw-r--r--\nEncrypted = {'+' if info.flag_bits & 0x1 else '-'}\nComment = \nCRC = {info.CRC:08X}\n")
            comp = info.compress_type
            method = "Store" if comp == zipfile.ZIP_STORED else "Deflate" if comp == zipfile.ZIP_DEFLATED else "BZip2" if comp == zipfile.ZIP_BZIP2 else "LZMA" if comp == zipfile.ZIP_LZMA else "Store"
            sys.stdout.write(f"Method = {method}\nCharacteristics = NTFS\nHost OS = Unix\nVersion = 10\nVolume Index = 0\nOffset = 0\n\n")
    else:
        sys.stdout.write("   Date      Time    Attr         Size   Compressed  Name\n------------------- ----- ------------ ------------  ------------------------\n")
        for info in infos:
            dt = datetime.datetime(*info.date_time)
            sys.stdout.write(f"{dt.strftime('%Y-%m-%d')} {dt.strftime('%H:%M:%S')} ..... {info.file_size:12} {info.compress_size:12}  {info.filename}\n")
        sys.stdout.write("------------------- ----- ------------ ------------  ------------------------\n")
        total_size = sum(i.file_size for i in infos)
        total_packed = sum(i.compress_size for i in infos)
        if infos:
            dt = datetime.datetime(*infos[0].date_time)
            sys.stdout.write(f"{dt.strftime('%Y-%m-%d')} {dt.strftime('%H:%M:%S')} {total_size:16} {total_packed:12}  {len(infos)} files\n")
        else:
            dt = datetime.datetime.now()
            sys.stdout.write(f"{dt.strftime('%Y-%m-%d')} {dt.strftime('%H:%M:%S')} {0:16} {0:12}  0 files\n")

def list_tar(archive, slt):
    sz = os.path.getsize(archive)
    sys.stdout.write("--\n")
    sys.stdout.write(f"Path = {archive}\nType = tar\nPhysical Size = {sz}\n")
    try:
        tf = tarfile.open(archive, 'r')
        members = tf.getmembers()
        tf.close()
    except:
        members = []
    headers_size = len(members)*512 + 1024
    if headers_size > sz:
        headers_size = sz//2
    sys.stdout.write(f"Headers Size = {headers_size}\nCode Page = UTF-8\nCharacteristics = GNU ASCII\n\n")
    if slt:
        for m in members:
            sys.stdout.write("----------\n")
            sys.stdout.write(f"Path = {m.name}\nFolder = {'+' if m.isdir() else '-'}\nSize = {m.size}\n")
            packed = ((m.size + 511)//512)*512 if m.isfile() else 0
            sys.stdout.write(f"Packed Size = {packed}\n")
            dt = datetime.datetime.fromtimestamp(m.mtime)
