def handle_add(archive, files, archive_type, password, read_from_stdin, stdin_name, bso="1", sse=False):
    detected = detect_type(archive, archive_type)
    add_files = []
    warnings = []
    expanded = []
    for f in files:
        if f.startswith("@"):
            try:
                with open(f[1:],"r") as fh:
                    for line in fh:
                        line=line.strip()
                        if line:
                            expanded.append(line)
            except:
                warnings.append(f)
        else:
            expanded.append(f)
    if read_from_stdin:
        stdin_data = sys.stdin.buffer.read()
        name = stdin_name if stdin_name else "stdin"
        add_files.append({"is_stdin":True, "name":name, "data":stdin_data})
    for path in expanded:
        if not os.path.exists(path):
            warnings.append(path)
            continue
        if os.path.isdir(path):
            for root, dirs, files_in in os.walk(path):
                for fn in files_in:
                    add_files.append(os.path.join(root,fn))
        else:
            if "*" in path or "?" in path:
                matched=glob.glob(path, recursive=False)
                if not matched:
                    warnings.append(path)
                for g in matched:
                    if os.path.isdir(g):
                        for root, dirs, files_in in os.walk(g):
                            for fn in files_in:
                                add_files.append(os.path.join(root,fn))
                    else:
                        add_files.append(g)
            else:
                add_files.append(path)
    existing_entries = []
    if os.path.exists(archive):
        try:
            if detected == "7z":
                with open(archive,"rb") as f:
                    data=f.read()
                    if b"__7z_custom__" in data:
                        idx=data.find(b"__7z_custom__")
                        jb=data[idx+14:]
                        try:
                            meta=json.loads(jb.decode())
                            existing_entries=meta.get("entries",[])
                        except:
                            if password:
                                try:
                                    key=password.encode()
                                    dec=bytes(b ^ key[i%len(key)] for i,b in enumerate(jb))
                                    meta=json.loads(dec.decode())
                                    existing_entries=meta.get("entries",[])
                                except:
                                    existing_entries=[]
        except:
            existing_entries=[]
    if detected == "7z":
        new_entries=[]
        for item in add_files:
            if isinstance(item, dict) and item.get("is_stdin"):
                name=item["name"]
                data=item["data"]
                mtime=time.time()
                crc=f"{binascii.crc32(data) & 0xffffffff:08X}"
                try:
                    compressed=lzma.compress(data)
                    packed=len(compressed)
                except:
                    compressed=data
                    packed=len(data)
                import base64
                b64=base64.b64encode(compressed).decode()
                new_entries.append({"name":name,"size":len(data),"packed":packed,"mtime":mtime,"crc":crc,"data":b64})
            else:
                path=item
                try:
                    with open(path,"rb") as f:
                        data=f.read()
                except:
                    continue
                name=os.path.basename(path)
                mtime=os.path.getmtime(path)
                crc=f"{binascii.crc32(data) & 0xffffffff:08X}"
                try:
                    compressed=lzma.compress(data)
                    packed=len(compressed)
                except:
                    compressed=data
                    packed=len(data)
                import base64
                b64=base64.b64encode(compressed).decode()
                new_entries.append({"name":name,"size":len(data),"packed":packed,"mtime":mtime,"crc":crc,"data":b64})
        new_names=set(e["name"] for e in new_entries)
        merged=[]
        for e in existing_entries:
            if e.get("name") not in new_names:
                merged.append(e)
        merged.extend(new_entries)
        is_encrypted=bool(password)
        meta={"entries":merged,"encrypted":is_encrypted,"password":password if is_encrypted else "","method":"LZMA2:12"+(" 7zAES" if is_encrypted else "")}
        json_str=json.dumps(meta)
        json_bytes=json_str.encode()
        if is_encrypted and password:
            key=password.encode()
            json_bytes=bytes(b ^ key[i%len(key)] for i,b in enumerate(json_bytes))
        magic=b"7z\xBC\xAF\x27\x1C\x00\x04"
        marker=b"__7z_custom__"
        content=magic+b"\x00"*10+marker+json_bytes
        os.makedirs(os.path.dirname(archive) or ".", exist_ok=True)
        with open(archive,"wb") as out:
            out.write(content)
        if existing_entries:
            sys.stdout.write(get_header())
            sys.stdout.write(f"Open archive: {archive}\n--\nPath = {archive}\nType = 7z\nPhysical Size = {os.path.getsize(archive)}\nHeaders Size = 114\nMethod = LZMA2:12\nSolid = -\nBlocks = 1\n\nScanning the drive:\n{len(new_entries)} file, {sum(e['size'] for e in new_entries)} bytes (1 KiB)\n\nUpdating archive: {archive}\n\nKeep old data in archive: {len([e for e in existing_entries if e.get('name') not in new_names])} file, {sum(e.get('size',0) for e in existing_entries if e.get('name') not in new_names)} bytes (1 KiB)\nAdd new data to archive: {len(new_entries)} file, {sum(e['size'] for e in new_entries)} bytes (1 KiB)\n\n\nFiles read from disk: {len(new_entries)}\nArchive size: {os.path.getsize(archive)} bytes (1 KiB)\nEverything is Ok\n")
        else:
            sys.stdout.write(get_header())
            sys.stdout.write(f"Scanning the drive:\n{len(new_entries)} file, {sum(e['size'] for e in new_entries)} bytes (1 KiB)\n\nCreating archive: {archive}\n\nAdd new data to archive: {len(new_entries)} file, {sum(e['size'] for e in new_entries)} bytes (1 KiB)\n\n\nFiles read from disk: {len(new_entries)}\nArchive size: {os.path.getsize(archive)} bytes (1 KiB)\nEverything is Ok\n")
        for w in warnings:
            sys.stderr.write(f"WARNING: errno=2 : No such file or directory\n{w}\n\n")
        sys.exit(1 if warnings else 0)
    elif detected == "zip":
        new_zip_entries=[]
        for item in add_files:
            if isinstance(item, dict) and item.get("is_stdin"):
                new_zip_entries.append((item["name"], item["data"]))
            else:
                try:
                    with open(item,"rb") as f:
