                pass
        os.makedirs(os.path.dirname(archive) or ".", exist_ok=True)
        with zipfile.ZipFile(archive,'w', compression=zipfile.ZIP_STORED) as z:
            for name, data in existing_zip_data.items():
                z.writestr(name, data)
            for name, data in new_zip_entries:
                z.writestr(name, data)
        sys.stdout.write(get_header())
        if existing_entries:
            sys.stdout.write(f"Open archive: {archive}\n--\nPath = {archive}\nType = zip\nPhysical Size = {os.path.getsize(archive)}\n\nScanning the drive:\n{len(new_zip_entries)} file, {sum(len(d) for _,d in new_zip_entries)} bytes (1 KiB)\n\nUpdating archive: {archive}\n\nAdd new data to archive: {len(new_zip_entries)} file, {sum(len(d) for _,d in new_zip_entries)} bytes (1 KiB)\n\n\nFiles read from disk: {len(new_zip_entries)}\nArchive size: {os.path.getsize(archive)} bytes (1 KiB)\nEverything is Ok\n")
        else:
            sys.stdout.write(f"Scanning the drive:\n{len(new_zip_entries)} file, {sum(len(d) for _,d in new_zip_entries)} bytes (1 KiB)\n\nCreating archive: {archive}\n\nAdd new data to archive: {len(new_zip_entries)} file, {sum(len(d) for _,d in new_zip_entries)} bytes (1 KiB)\n\n\nFiles read from disk: {len(new_zip_entries)}\nArchive size: {os.path.getsize(archive)} bytes (1 KiB)\nEverything is Ok\n")
        for w in warnings:
            sys.stderr.write(f"WARNING: errno=2 : No such file or directory\n{w}\n\n")
        sys.exit(1 if warnings else 0)
    elif detected == "tar":
        new_tar_entries=[]
        for item in add_files:
            if isinstance(item, dict) and item.get("is_stdin"):
                new_tar_entries.append((item["name"], item["data"]))
            else:
                try:
                    with open(item,"rb") as f:
                        new_tar_entries.append((os.path.basename(item), f.read()))
                except:
                    continue
        existing_tar_data={}
        if os.path.exists(archive):
            try:
                tf=tarfile.open(archive,'r')
                for m in tf.getmembers():
                    if m.isfile() and m.name not in [n for n,_ in new_tar_entries]:
                        f=tf.extractfile(m)
                        existing_tar_data[m.name]=f.read() if f else b""
                tf.close()
            except:
                pass
        os.makedirs(os.path.dirname(archive) or ".", exist_ok=True)
        with tarfile.open(archive,'w') as tf:
            for name, data in existing_tar_data.items():
                ti=tarfile.TarInfo(name=name)
                ti.size=len(data)
                ti.mtime=int(time.time())
                ti.mode=0o644
                tf.addfile(ti, fileobj=tarfile.io.BytesIO(data))
            for name, data in new_tar_entries:
                ti=tarfile.TarInfo(name=name)
                ti.size=len(data)
                ti.mtime=int(time.time())
                ti.mode=0o644
                tf.addfile(ti, fileobj=tarfile.io.BytesIO(data))
        sys.stdout.write(get_header())
        if existing_entries:
            sys.stdout.write(f"Open archive: {archive}\n--\nPath = {archive}\nType = tar\nPhysical Size = {os.path.getsize(archive)}\nHeaders Size = 1536\nCode Page = UTF-8\nCharacteristics = GNU ASCII\n\nScanning the drive:\n{len(new_tar_entries)} file, {sum(len(d) for _,d in new_tar_entries)} bytes (1 KiB)\n\nUpdating archive: {archive}\n\nAdd new data to archive: {len(new_tar_entries)} file, {sum(len(d) for _,d in new_tar_entries)} bytes (1 KiB)\n\nFiles read from disk: {len(new_tar_entries)}\nArchive size: {os.path.getsize(archive)} bytes (1 KiB)\nEverything is Ok\n")
        else:
