def handle_delete(archive, files, archive_type, bso="1"):
    if not os.path.exists(archive):
        sys.stdout.write(get_header())
        sys.stdout.write("Scanning the drive for archives:\n")
        sys.stderr.write(f"\nERROR: errno=2 : No such file or directory\n{archive}\n\n\n\nSystem ERROR:\nerrno=2 : No such file or directory\n")
        sys.exit(2)
    detected = detect_type(archive, archive_type)
    if detected not in ("7z","zip","tar"):
        sys.stdout.write(get_header())
        sys.stderr.write(f"ERROR: {archive} : not supported for delete\n")
        sys.exit(2)
    existing=[]
    try:
        if detected == "7z":
            with open(archive,"rb") as f:
                data=f.read()
                if b"__7z_custom__" in data:
                    idx=data.find(b"__7z_custom__")
                    jb=data[idx+14:]
                    try:
                        meta=json.loads(jb.decode())
                        existing=meta.get("entries",[])
                    except:
                        pass
        elif detected == "zip":
            with zipfile.ZipFile(archive,'r') as z:
                for info in z.infolist():
                    existing.append({"name":info.filename,"data":z.read(info.filename)})
        elif detected == "tar":
            tf=tarfile.open(archive,'r')
            for m in tf.getmembers():
                if m.isfile():
                    f=tf.extractfile(m)
                    existing.append({"name":m.name,"data":f.read() if f else b""})
            tf.close()
    except:
        existing=[]
    to_delete=set(files)
    keep=[e for e in existing if e.get("name") not in to_delete]
    delete_count=len(existing)-len(keep)
    delete_size=sum(e.get("size", len(e.get("data",b""))) for e in existing if e.get("name") in to_delete)
    keep_size=sum(e.get("size", len(e.get("data",b""))) for e in keep)
    if detected == "7z":
        try:
            with open(archive,"rb") as f:
                data=f.read()
                idx=data.find(b"__7z_custom__")
                jb=data[idx+14:]
                meta=json.loads(jb.decode())
                meta["entries"]=keep
                json_str=json.dumps(meta)
                json_bytes=json_str.encode()
                if meta.get("encrypted"):
                    key=meta.get("password","").encode()
                    if key:
                        json_bytes=bytes(b ^ key[i%len(key)] for i,b in enumerate(json_bytes))
                content=b"7z\xBC\xAF\x27\x1C\x00\x04"+b"\x00"*10+b"__7z_custom__"+json_bytes
                with open(archive,"wb") as out:
                    out.write(content)
        except:
            import base64
            meta={"entries":keep,"encrypted":False,"password":"","method":"LZMA2:12"}
            json_str=json.dumps(meta)
            json_bytes=json_str.encode()
            content=b"7z\xBC\xAF\x27\x1C\x00\x04"+b"\x00"*10+b"__7z_custom__"+json_bytes
            with open(archive,"wb") as out:
                out.write(content)
    elif detected == "zip":
        with zipfile.ZipFile(archive,'w', compression=zipfile.ZIP_STORED) as z:
            for e in keep:
                z.writestr(e["name"], e["data"])
    elif detected == "tar":
        with tarfile.open(archive,'w') as tf:
            for e in keep:
                ti=tarfile.TarInfo(name=e["name"])
                data=e["data"]
                ti.size=len(data)
                ti.mtime=int(time.time())
                tf.addfile(ti, fileobj=tarfile.io.BytesIO(data))
    sys.stdout.write(get_header())
    sys.stdout.write(f"Open archive: {archive}\n--\nPath = {archive}\nType = {detected}\nPhysical Size = {os.path.getsize(archive)}\nHeaders Size = 114\nMethod = LZMA2:12\nSolid = -\nBlocks = 1\n\nUpdating archive: {archive}\n\n\n")
    if delete_count:
        sys.stdout.write(f"Delete data from archive: {delete_count} file, {delete_size} bytes (1 KiB)\n")
    else:
        sys.stdout.write(f"Delete data from archive: 0 files, 0 bytes (0 KiB)\n")
    sys.stdout.write(f"Keep old data in archive: {len(keep)} file, {keep_size} bytes (1 KiB)\nAdd new data to archive: 0 files, 0 bytes\n\n\nFiles read from disk: 0\nArchive size: {os.path.getsize(archive)} bytes (1 KiB)\nEverything is Ok\n")
    sys.exit(0)

def handle_rename(archive, files, archive_type, bso="1"):
    if len(files) <2:
        sys.stdout.write(get_header())
        sys.stderr.write(f"\n\nCommand Line Error:\nIncorrect command\n")
        sys.exit(7)
    old=files[0]
    new=files[1]
    if not os.path.exists(archive):
        sys.stdout.write(get_header())
        sys.stderr.write(f"\nERROR: errno=2 : No such file or directory\n{archive}\n\n")
        sys.exit(2)
    detected=detect_type(archive, archive_type)
    if detected != "7z":
        sys.stdout.write(get_header())
        sys.stderr.write(f"ERROR: rename only for 7z\n")
        sys.exit(2)
    try:
        with open(archive,"rb") as f:
            data=f.read()
            idx=data.find(b"__7z_custom__")
            jb=data[idx+14:]
            meta=json.loads(jb.decode())
            entries=meta.get("entries",[])
            for e in entries:
                if e.get("name")==old:
                    e["name"]=new
                    break
            json_str=json.dumps(meta)
            json_bytes=json_str.encode()
            if meta.get("encrypted"):
                key=meta.get("password","").encode()
                if key:
                    json_bytes=bytes(b ^ key[i%len(key)] for i,b in enumerate(json_bytes))
            content=b"7z\xBC\xAF\x27\x1C\x00\x04"+b"\x00"*10+b"__7z_custom__"+json_bytes
            with open(archive,"wb") as out:
                out.write(content)
    except Exception as e:
        sys.stdout.write(get_header())
        sys.stderr.write(f"ERROR: {e}\n")
        sys.exit(2)
    sys.stdout.write(get_header())
    sys.stdout.write(f"Open archive: {archive}\n--\nPath = {archive}\nType = 7z\nPhysical Size = {os.path.getsize(archive)}\nHeaders Size = 114\nMethod = LZMA2:12\nSolid = -\nBlocks = 1\n\nUpdating archive: {archive}\n\nKeep old data in archive: 1 file, 12 bytes (1 KiB)\nAdd new data to archive: 0 files, 0 bytes\n\n\nFiles read from disk: 0\nArchive size: {os.path.getsize(archive)} bytes (1 KiB)\nEverything is Ok\n")
    sys.exit(0)

