def handle_hash(remaining):
    scrc = "CRC32"
    bso = "1"
    files = []
    stop=False
    for arg in remaining:
        if arg == "--":
            stop=True
            continue
        if not stop and arg.startswith("-"):
            if arg.startswith("-scrc"):
                val = arg[5:]
                if val.startswith("="):
                    val = val[1:]
                if val == "":
                    scrc = "*"
                else:
                    scrc = val
                continue
            elif arg.startswith("-bb") or arg == "-bd":
                continue
            elif arg.startswith("-bs"):
                if arg in ("-bso0","-bso1","-bso2","-bse0","-bse1","-bse2","-bsp0","-bsp1","-bsp2"):
                    if arg.startswith("-bso"):
                        bso = arg[4]
