        if not os.path.exists(path):
            warnings.append(path)
            continue
        if os.path.isdir(path):
            for root, dirs, files_in in os.walk(path):
                for fn in files_in:
                    hash_files.append(os.path.join(root, fn))
        else:
            if "*" in path or "?" in path:
                matched = glob.glob(path, recursive=False)
                if not matched:
                    warnings.append(path)
                for g in matched:
                    if os.path.isdir(g):
