            table_stream.write(f"{chs['CRC32']:8} {chs['CRC64']:16} {chs['SHA256']:64} {chs['SHA1']:40} {chs['XXH64']:16} {len(combined):13}  \n")
    else:
        if len(hash_names)==1:
            table_stream.write(f"{'':8} {0:13}  \n")
        else:
