def detect_type(path, override=None):
    if override:
        ov = override.lower()
        if ov == "gz":
            return "gzip"
        if ov == "bz2":
            return "bzip2"
        if ov in ("7z","zip","tar","gzip","bzip2","xz"):
            return ov
        return ov
    ext = os.path.splitext(path)[1].lower()
    if ext == ".7z":
        return "7z"
    elif ext == ".zip":
        return "zip"
    elif ext == ".tar":
        return "tar"
    elif ext in (".gz",".tgz"):
        return "gzip"
    elif ext == ".bz2":
        return "bzip2"
    elif ext == ".xz":
        return "xz"
    else:
        try:
            with open(path, "rb") as f:
                magic = f.read(10)
                if magic.startswith(b"7z\xBC\xAF\x27\x1C"):
                    return "7z"
                elif magic.startswith(b"PK\x03\x04"):
                    return "zip"
                elif magic.startswith(b"\x1F\x8B"):
                    return "gzip"
                elif magic.startswith(b"BZh"):
                    return "bzip2"
                elif magic.startswith(b"\xFD7zXZ\x00"):
                    return "xz"
        except:
            pass
        return "7z"

