            method = "Store" if comp == zipfile.ZIP_STORED else "Deflate" if comp == zipfile.ZIP_DEFLATED else "BZip2" if comp == zipfile.ZIP_BZIP2 else "LZMA" if comp == zipfile.ZIP_LZMA else "Store"
